async function generateUpsellBundle(cartItem: string) {
  // 1. Semantic search for complementary products
  const matches = await vectorDb.query({ text: cartItem, topK: 5 });

  // 2. Filter for high-margin items in stock
  const highMarginSkus = matches.filter(sku => sku.margin > 40 && sku.stock > 0).slice(0, 2);

  if (highMarginSkus.length === 2) {
    // 3. Generate a personalized bundle name and calculate discount
    const bundleName = await llm.generateTitle(cartItem, highMarginSkus);
    const originalPrice = highMarginSkus.reduce((sum, item) => sum + item.price, 0);
    const bundlePrice = originalPrice * 0.90; // 10% Upsell Discount

    return {
      title: bundleName,
      items: highMarginSkus,
      offerPrice: bundlePrice
    };
  }
  return null;
}

